/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to prices from Trade Agreements and add entry to Price Change tracking table for later processing
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeEvent))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, TradeAgreement))]
public class METPriceChangeEventTradeAgreement extends METPriceChangeEvent
{
    PriceDiscAdmTable           priceDiscAdmTable;
    METPriceAttributeEnabled    priceAttributeEnabled;
    RecordInsertList            priceChangeTrackingList;

}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void initInstance(Common _common, SysAppCRUDOperation _crud)
{
    this.setInternals(_Common, _crud);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    super(_common, _crud);
    priceDiscAdmTable       = _common as PriceDiscAdmTable;
    priceAttributeEnabled   = priceDiscAdmTable.priceDiscPriceAttributeEnable();
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::TradeAgreement;
}

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    public void process()
    {
        PriceDiscAdmTrans       priceDiscAdmTrans;
        
        if( priceDiscAdmTable.Posted && priceDiscAdmTable.DefaultRelation == PriceType::PriceSales)
        {
            priceChangeTrackingList = new RecordInsertList(tableNum(METPriceChangeTracking));

            if(priceAttributeEnabled)
            {
                while select priceDiscAdmTrans
                    where   priceDiscAdmTrans.JournalNum    == priceDiscAdmTable.JournalNum
                {
                    this.setStandardValues(priceDiscAdmTrans);
                    
                    priceChangeTracking.PriceAttributeEnabled           = priceAttributeEnabled;
                    priceChangeTracking.PricingAttributeGroupHeader     = priceDiscAdmTrans.displayPricingAttributeGroupNameHeader();
                    priceChangeTracking.PricingAttributeDetailsHeader   = priceDiscAdmTrans.pricingAttributeDetailsHeader();
                    priceChangeTracking.PricingAttributeGroupLine       = priceDiscAdmTrans.displayPricingAttributeGroupNameLine();
                    priceChangeTracking.PricingAttributeDetailsLine     = priceDiscAdmTrans.pricingAttributeDetailsLine();
                    priceChangeTracking.PricingRuleHeader               = priceDiscAdmTrans.PricingRuleHeader;
                    priceChangeTracking.PricingRuleLine                 = priceDiscAdmTrans.PricingRuleLine;

                    priceChangeTrackingList.add(priceChangeTracking);
                    
                }
            }
            else
            {
                while select priceDiscAdmTrans
                    where   priceDiscAdmTrans.JournalNum    == priceDiscAdmTable.JournalNum
                    &&      priceDiscAdmTrans.ItemCode      == PriceDiscProductCodeType::Table
                    &&     (priceDiscAdmTrans.AccountCode   == PriceDiscPartyCodeType::GroupId || priceDiscAdmTrans.AccountCode  == PriceDiscPartyCodeType::Table)
                {
                    this.setStandardValues(priceDiscAdmTrans);
                    
                    priceChangeTracking.PriceDiscPartyCode      = priceDiscAdmTrans.AccountCode;
                    priceChangeTracking.PriceDiscAccountRelation = priceDiscAdmTrans.AccountRelation;
                    priceChangeTracking.ItemId                  = priceDiscAdmTrans.itemCode == PriceDiscProductCodeType::Table ? priceDiscAdmTrans.ItemRelation : blankValue;
                    
                    priceChangeTrackingList.add(priceChangeTracking);
                }
            }
            ttsbegin;
            priceChangeTrackingList.insertDatabase();
            ttscommit;
        }
    }

/// <summary>
/// Set standard values
/// </summary>
/// <param name = "_priceDiscAdmTrans">Trade agreement line</param>
public void setStandardValues(PriceDiscAdmTrans _priceDiscAdmTrans)
{
    priceChangeTracking.clear();
    this.setCommonValues(_priceDiscAdmTrans);
    priceChangeTracking.PriceDiscJournalNum     = _priceDiscAdmTrans.JournalNum;
    priceChangeTracking.PriceDiscLineNum        = _priceDiscAdmTrans.LineNum;
    priceChangeTracking.FromDate                = this.getFromDate(_priceDiscAdmTrans.FromDate);
    priceChangeTracking.ToDate                  = _priceDiscAdmTrans.ToDate;
    priceChangeTracking.InventSiteId            = InventDim::find(_priceDiscAdmTrans.inventDimId).InventSiteId;
    priceChangeTracking.UnitId                  = _priceDiscAdmTrans.UnitId;
    priceChangeTracking.Price                   = _priceDiscAdmTrans.amount;
    priceChangeTracking.PriceQty                = _priceDiscAdmTrans.priceUnit;
    priceChangeTracking.QuantityAmountFrom      = this.getFromQty(_priceDiscAdmTrans.QuantityAmountFrom);
    priceChangeTracking.QuantityAmountTo        = _priceDiscAdmTrans.QuantityAmountTo;
}
